import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange?: (value: Date | null) => void;
}

function startOfDay(date: Date): Date {
  const copy = new Date(date);
  copy.setHours(0, 0, 0, 0);
  return copy;
}

function addDays(date: Date, days: number): Date {
  const copy = new Date(date);
  copy.setDate(copy.getDate() + days);
  return copy;
}

const quickOptions = [
  { value: 'today', label: 'Сегодня', getDate: () => startOfDay(new Date()) },
  { value: 'yesterday', label: 'Вчера', getDate: () => startOfDay(addDays(new Date(), -1)) },
  { value: 'week-ago', label: 'Неделя назад', getDate: () => startOfDay(addDays(new Date(), -7)) },
];

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [date, setDate] = useState<Date | null>(null);
  const [activeQuick, setActiveQuick] = useState<string | null>(null);

  const handleDateChange = (value: Date | null) => {
    setDate(value);
    setActiveQuick(null);
    onChange?.(value);
  };

  const handleQuickSelect = (option: (typeof quickOptions)[number]) => {
    const nextDate = option.getDate();
    setDate(nextDate);
    setActiveQuick(option.value);
    onChange?.(nextDate);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
      <div style={{ display: 'flex', gap: 'var(--jx-r-xs)' }}>
        {quickOptions.map((option) => (
          <JxChip
            key={option.value}
            active={activeQuick === option.value}
            onClick={() => handleQuickSelect(option)}
          >
            {option.label}
          </JxChip>
        ))}
      </div>
      <JxCalendar locale="ru-RU" value={date} onValueChange={handleDateChange} />
    </div>
  );
}

